-- Taninan zincir subeleri. OpenStreetMap merkez noktalari.
-- address_place_id, 1.5 km icindeki mahalle satiridir.
ON CONFLICT (id) DO UPDATE SET brand_id = EXCLUDED.brand_id, name = EXCLUDED.name, name_folded = EXCLUDED.name_folded, category = EXCLUDED.category, address_place_id = EXCLUDED.address_place_id, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude;

